#include "dither_tuning.hpp"

namespace png2amiga::dither_tuning {

// Empirical mean-PSNR maxima (Floyd-Steinberg) over the 10 example
// images, per encoder context. Generated by the per-mode sweep on
// scap-lores-5bpp; see commit log for grid details.
//
// Conservative default for unlisted contexts: strength=1.0,
// error_clamp=0.35 — the pre-tuning whole-codebase baseline.
Defaults defaults_for(const Context& ctx) {
    constexpr Defaults kFallback{1.0f, 0.35f};

    if (ctx.scap) {
        if (ctx.dpf)        return Defaults{0.9f, 0.10f};
        if (ctx.mode == amiga::Mode::ehb)
                            return Defaults{0.9f, 0.20f};
        if (ctx.mode == amiga::Mode::lores && ctx.depth == 5)
                            return Defaults{0.9f, 0.10f};
        return kFallback;
    }

    if (ctx.mode == amiga::Mode::ehb) return Defaults{0.9f, 0.35f};

    if (ctx.mode == amiga::Mode::lores) {
        switch (ctx.depth) {
            case 1: return Defaults{1.0f, 0.35f};
            case 2: return Defaults{0.8f, 0.10f};
            case 3: return Defaults{0.9f, 0.35f};
            case 4: return Defaults{0.9f, 0.20f};
            case 5: return Defaults{0.9f, 0.35f};
            default: break;  // depth 6+ falls through (AGA territory)
        }
    }

    return kFallback;
}

} // namespace png2amiga::dither_tuning
